out_display equ 0x80
out_indicator equ 0x10
indicator equ 0x40
ldi b, clear_loop
ldi c, 32
ldi d, display
clear_loop:
  st a, d
  inc d
  dec c
  jnz b
loop:
  ld a, x
  ld b, y
xy_to_pos:
  ldi c, 7
  and c, a
  shr a
  shr a
  shr a
  shl b
  add b, a
  ldi a, display
  add b, a
  shl a
  pos_loop:
    shr a
    dec c
    jns pos_loop
  rcl a
ld d, rotate
ld c, b
xor c, a
st c, b
and c, a
jz black
white:
  inc d
  jmp end_color
black:
  dec d
end_color:
  ldi a, 3
  and d, a
  st d, rotate
  jmp read_change_xy
rotates db
0, 1,
0 - 1, 0,
0, 0 - 1,
1, 0
rotate db 1
step_count db 0
x db 8
y db 8
in db 0
out db out_display
display db          0b00000000, 0b00000000,
                    0b00000000, 0b00000000,
                    0b10010000, 0b00000000,
                    0b01001000, 0b00000000,
                    0b01001000, 0b00000000,
                    0b01111000, 0b00000000,
                    0b11111011, 0b00011000,
                    0b11011111, 0b10111100,
                    0b01110111, 0b11111110,
                    0b00000111, 0b10111111,
                    0b00001001, 0b00001000,
                    0b00010010, 0b00000100,
                    0b00100100, 0b00000010,
                    0b00000000, 0b00000000,
                    0b00000000, 0b00000000,
                    0b00000000, 0b00000000
read_change_xy:
  shl d
  ldi a, rotates
  add a, d
  ld b, a
  inc a
  ld c, a
  ld a, x
  add b, a
  ld a, y
  add c, a
  ldi a, 15
  and b, a
  and c, a
  st b, x
  st c, y
output_step:
  ld b, display
  ldi a, out_indicator
  st a, out
  ld a, step_count
  inc a
  st a, step_count
  st a, indicator
  ldi a, out_display
  st a, out
  st b, display
  jmp loop


